```rust
pub fn compile(&'a self, plugin: &(impl FormatPlugin + ?Sized)) -> Result<()> {
    let ext = plugin.extension();
    match ext {
        "pdf" => self.compile_to_pdf(plugin),
        "html" => self.compile_to_html(plugin),
        _ => Err(RheoError::misconfigured_plugin(
