```rust
fn inject_post_compilation_assets(
    &self,
    output_path: &Path,
    assets: &HashMap<&'static str, Vec<Asset>>,
) -> Result<()> {
    let css_paths: Vec<&str> = assets
        .get(&STYLESHEETS)
        .map(|v| v.iter().map(|a| a.built_relative_path.as_str()).collect())
        .unwrap_or_default();
    let js_paths: Vec<&str> = assets
        .get(&SCRIPTS)
        .map(|v| v.iter().map(|a| a.built_relative_path.as_str()).collect())
        .unwrap_or_default();

    if css_paths.is_empty() && js_paths.is_empty() {
        return Ok(());
    }

    let html = std::fs::read_to_string(output_path).map_err(|e| {
        RheoError::io(e, format!("reading {} for post-compile asset injection", output_path.display()))
    })?;
    let updated = html_utils::inject_head_links(&html, &[], &css_paths, &js_paths)?;
    std::fs::write(output_path, updated).map_err(|e| {
        RheoError::io(e, format!("writing {} after post-compile asset injection", output_path.display()))
    })?;
    Ok(())
}
```

