pub struct ResolvedPackage {
    pub name: String,
    pub source_root: PathBuf,
    /// Present for @namespace/name:version imports; None for relative-path packages.
    pub namespace: Option<String>,
    pub version: Option<String>,
}
```

   Update `resolve_packages` and `default_package_assets` call sites to populate `namespace`/`version` as `None` for relative paths and `Some(...)` for `@preview/...` (using the new parser helper from step 2).

2. Add a shared parser in `crates/core/src/plugins/mod.rs`:

```rust
/// Parse `@namespace/name:version` into its components. Returns None on malformed input.
pub fn parse_package_spec(spec: &str) -> Option<(&str, &str, &str)> {
    let without_at = spec.strip_prefix('@')?;
    let slash = without_at.find('/')?;
    let namespace = &without_at[..slash];
    let rest = &without_at[slash + 1..];
    let colon = rest.rfind(':')?;
    let name = &rest[..colon];
    let version = &rest[colon + 1..];
    if namespace.is_empty() || name.is_empty() || version.is_empty() {
        return None;
    }
    Some((namespace, name, version))
}
```

   Use this from `resolve_packages` instead of the inline parsing block (preserving its error semantics — `resolve_packages` returns `Err` on malformed spec; auto-detect returns `None`).

3. In `crates/core/src/plugins/typst_manifest.rs`, add:

```rust
use crate::plugins::{ResolvedPackage, parse_package_spec};
use std::path::{Path, PathBuf};

/// Probe `search_dirs` (in order) for `{namespace}/{name}/{version}/`.
/// Returns the resolved package directory the first time it's found.
/// Pure with respect to `dirs::*` — `find_local_package_dir` is the thin wrapper that injects system dirs.
pub fn find_package_in_dirs(spec: &str, search_dirs: &[PathBuf]) -> Option<ResolvedPackage> {
    let (namespace, name, version) = parse_package_spec(spec)?;
    let rel = Path::new(namespace).join(name).join(version);
    let source_root = search_dirs.iter().map(|d| d.join(&rel)).find(|p| p.is_dir())?;
    Some(ResolvedPackage {
        name: name.to_string(),
        source_root,
        namespace: Some(namespace.to_string()),
        version: Some(version.to_string()),
    })
}

/// Production resolver: probes Typst's data dir then cache dir.
pub fn find_local_package_dir(spec: &str) -> Option<ResolvedPackage> {
    let dirs: Vec<PathBuf> = [
        dirs::data_dir().map(|d| d.join("typst/packages")),
        dirs::cache_dir().map(|d| d.join("typst/packages")),
    ]
    .into_iter()
    .flatten()
    .collect();
    find_package_in_dirs(spec, &dirs)
}
```

