1. In crates/cli/src/lib.rs, add a private helper near resolve_assets:

   /// Default combiner used when AssetConfig.combine is None: copies each source
   /// verbatim into the build dir, preserving its path relative to the project root.
   fn default_copy_each(
       sources: &[PathBuf],
       project_root: &Path,
       build_dir: &Path,
   ) -> Result<Vec<PathBuf>> {
       let mut out = Vec::with_capacity(sources.len());
       for src in sources {
           let rel = src.strip_prefix(project_root).expect("source is always project_root-joined");
           let dest = build_dir.join(rel);
           if let Some(parent) = dest.parent() {
               std::fs::create_dir_all(parent)
                   .map_err(|e| RheoError::io(e, format!("creating directory for asset '{}'", rel.display())))?;
           }
           std::fs::copy(src, &dest).map_err(|e| RheoError::AssetCopy {
               source: src.clone(), dest: dest.clone(), error: e,
           })?;
           out.push(dest);
       }
       Ok(out)
   }

   Note: use .expect("source is always project_root-joined") not .unwrap_or(src.as_path()) since all sources are constructed as project_root.join(path) in step 2 below. Match the existing error message style: "creating directory for asset" (not "creating dir") and quote the path.

2. Rewrite the body of resolve_assets (lines 377-423):

   fn resolve_assets(
       plugin: &dyn FormatPlugin,
       plugin_section: &PluginSection,
       project_root: &Path,
       plugin_output_dir: &Path,
   ) -> Result<HashMap<&'static str, Vec<Asset>>> {
       let mut resolved = HashMap::new();
       for asset_config in plugin.assets() {
           // 1. Collect override paths across all [[plugin.assets]] blocks.
           let overrides: Vec<&str> = plugin_section.get_strings(asset_config.name);
           let effective: Vec<&str> = if overrides.is_empty() {
               vec![asset_config.default_path]
           } else {
               overrides
           };

           // 2. Resolve to absolute paths and check existence.
           let mut sources: Vec<PathBuf> = Vec::new();
           let mut missing: Vec<&str> = Vec::new();
           for path in &effective {
               let abs = project_root.join(path);
               if abs.is_file() {
                   sources.push(abs);
               } else {
                   missing.push(path);
               }
           }

           // 3. If required and *no* sources resolvable, error.
           if sources.is_empty() {
               if asset_config.required {
                   return Err(RheoError::project_config(format!(
                       "plugin '{}' requires input '{}' but no source was found (tried: {})",
                       plugin.name(), asset_config.name, effective.join(", ")
                   )));
               }
               continue;
           }

           // 4. Warn about any missing override paths (non-fatal when at least one exists).
           for m in &missing {
               warn!(plugin = plugin.name(), asset = asset_config.name, path = %m,
                     "asset override path not found, skipping");
           }

           // 5. Dispatch to combine strategy. Always invoked (even for single source).
           let outputs: Vec<PathBuf> = match asset_config.combine {
               Some(c) => c.combine(&sources, plugin_output_dir)?,
               None => default_copy_each(&sources, project_root, plugin_output_dir)?,
           };

           // 6. Wrap into Asset values.
           let assets: Vec<Asset> = outputs.into_iter().map(|abs| {
               let rel = abs.strip_prefix(plugin_output_dir).unwrap_or(&abs).to_string_lossy().into_owned();
               Asset {
                   config: asset_config.clone(),
                   resolved_path: abs,
                   built_relative_path: rel,
               }
           }).collect();

           resolved.insert(asset_config.name, assets);
       }
       Ok(resolved)
   }

3. `use tracing::warn;` is already present at crates/cli/src/lib.rs:15.

