        rheo_core::plugins::scan_project_package_imports(&project.typ_files);
    let auto_blocks = rheo_core::plugins::detect_manifest_package_assets(
        &auto_import_paths,
        plugin.name(),
    );
    blocks.extend(auto_blocks);
    Ok(blocks)
}
```

